    visited = [[0 for _ in range(w)] for _ in range(h)]
    for i in range(h):
        for j in range(w):
            visited[i][j] = 1 if grid[i][j] == '.' else 0
    ans = 0
    for i in range(h):
        for j in range(w):
            if visited[i][j] == 1:
                cnt = 1
                for di, dj in dirs:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < h and 0 <= nj < w and visited[ni][nj] == 1:
                        cnt += 1
                ans += cnt * (cnt - 1) // 2
    return ans
